counts = collections.Counter(numbers)

def solve(idx, current_counts):
    if idx == len(zeros):
        for r in range(6):
            if sum(matrix[r][:6]) != matrix[r][6]: return False
        for c in range(6):
            if sum(matrix[i][c] for i in range(6)) != matrix[6][c]: return False
        return True

    r, c = zeros[idx]
    for num in sorted(current_counts.keys()):
        if current_counts[num] > 0:
            matrix[r][c] = num
            current_counts[num] -= 1

            # Optimization: check current row/col if they are finished
            row_finished = all(matrix[r][j] != 0 or (r, j) == (r, c) for j in range(6))
            # Wait, zeros are sorted by row then column, so a row is finished when zeros[idx][0] != zeros[idx+1][0]

