            # For column, it's harder to tell if it's finished without more logic
            # But we can check if sum already exceeds target
            if sum(matrix[i][c] for i in range(6) if matrix[i][c] != 0) > matrix[6][c]:
                col_ok = False
            # And if it's the last zero in the column, check equality
            is_last_zero_in_col = True
            for k in range(idx + 1, len(zeros)):
                if zeros[k][1] == c:
                    is_last_zero_in_col = False
                    break
            if is_last_zero_in_col:
                if sum(matrix[i][c] for i in range(6)) != matrix[6][c]:
                    col_ok = False

            if row_ok and col_ok:
                if solve(idx + 1, current_counts):
                    return True

            current_counts[num] += 1
            matrix[r][c] = 0
